import { useMemo, useState } from 'react';
import FormulaCard from '../components/FormulaCard';
import { useI18n } from '../i18n';

type LocaleText = { id: string; en: string };
type LessonSection = { heading: LocaleText; body: LocaleText[]; formula?: LocaleText; explanation?: LocaleText; tag?: 'theory' | 'game' };
type Lesson = { id: string; number: string; category: LocaleText; title: LocaleText; intro: LocaleText; sections: LessonSection[]; takeaway: LocaleText };
const tx = (id: string, en: string): LocaleText => ({ id, en });

const lessons: Lesson[] = [
  {
    id: 'overview', number: '01', category: tx('Fundamental', 'Fundamentals'), title: tx('Prinsip kerja BWR', 'How a BWR works'),
    intro: tx('Boiling Water Reactor (BWR) adalah reaktor air ringan yang mendidihkan air pendingin langsung di dalam bejana reaktor. Uap dipisahkan dari tetesan cairan dan digunakan untuk menggerakkan turbin.', 'A Boiling Water Reactor (BWR) is a light-water reactor that boils coolant directly inside the reactor vessel. Steam is separated from liquid droplets and used to drive a turbine.'),
    sections: [
      { heading: tx('Siklus langsung (direct cycle)', 'The direct cycle'), body: [tx('Energi fisi dipindahkan ke bahan bakar sebagai panas. Panas berpindah ke air pendingin dan sebagian air berubah menjadi uap di dalam bejana.', 'Fission energy heats the fuel. Heat transfers to the coolant, and some water boils into steam inside the vessel.'), tx('Steam separator dan dryer mengurangi tetesan air yang terbawa uap. Uap kemudian menuju turbin-generator, sedangkan uap buang dikondensasikan dan air dikembalikan sebagai feedwater.', 'Steam separators and dryers reduce liquid carryover. Steam then flows to the turbine-generator; exhaust steam is condensed and returned as feedwater.'), tx('Disebut siklus langsung karena uap yang menggerakkan turbin dibentuk di dalam bejana reaktor, berbeda dari PWR yang menggunakan steam generator terpisah.', 'It is called a direct cycle because turbine steam is generated inside the reactor vessel, unlike a PWR that uses a separate steam generator.')], formula: tx('Fisi → panas → uap → kerja poros → listrik', 'Fission → heat → steam → shaft work → electricity'), explanation: tx('Urutan konversi energi, bukan persamaan efisiensi atau nilai desain.', 'An energy-conversion sequence, not an efficiency equation or design value.') },
      { heading: tx('Batas sistem konseptual', 'Conceptual system boundary'), body: [tx('Diagram pembelajaran mencakup bejana/teras, pemisah uap, jalur uap, turbin-generator, kondensor, pompa, feedwater, dan sirkulasi.', 'The learning diagram includes the vessel/core, steam separation, steam line, turbine-generator, condenser, pumps, feedwater, and circulation.'), tx('Diagram live pada simulator adalah process flow diagram konseptual. Diagram tersebut bukan P&ID, bukan layout fasilitas, dan tidak memuat seluruh sistem keselamatan atau instrumentasi.', 'The simulator live diagram is a conceptual process flow diagram. It is not a P&ID or facility layout and does not represent every safety or instrumentation system.')], },
    ], takeaway: tx('Ciri pembeda BWR adalah air mendidih di dalam bejana reaktor dan uapnya digunakan langsung untuk turbin.', 'The defining BWR feature is that water boils inside the reactor vessel and its steam is used directly by the turbine.'),
  },
  {
    id: 'components', number: '02', category: tx('Sistem', 'Systems'), title: tx('Komponen utama BWR', 'Main BWR components'),
    intro: tx('Komponen dipahami melalui fungsi termal, hidraulik, dan konversi energinya. Penjelasan ini bersifat arsitektural, bukan instruksi pengoperasian.', 'Components are understood through their thermal, hydraulic, and energy-conversion roles. This is an architectural explanation, not operating instruction.'),
    sections: [
      { heading: tx('Reactor pressure vessel dan core', 'Reactor pressure vessel and core'), body: [tx('RPV merupakan batas tekanan yang menampung fluida kerja, teras, dan internal vessel. Teras berisi fuel assemblies tempat energi fisi dilepaskan.', 'The RPV is the pressure boundary containing working fluid, the core, and vessel internals. The core contains fuel assemblies where fission energy is released.'), tx('Air ringan berperan sebagai pendingin sekaligus moderator neutron. Perubahan temperatur dan pembentukan uap memengaruhi densitas moderator.', 'Light water acts as both coolant and neutron moderator. Temperature and steam formation affect moderator density.') ] },
      { heading: tx('Steam separator dan dryer', 'Steam separator and dryer'), body: [tx('Separator memisahkan sebagian besar cairan dari campuran uap-air. Dryer mengurangi kelembapan sebelum uap meninggalkan bejana menuju turbin.', 'The separator removes much of the liquid from the steam-water mixture. The dryer reduces moisture before steam leaves the vessel for the turbine.'), tx('Pemisahan tidak membuat aliran dua fase menjadi persoalan sederhana: distribusi lokal, droplet carryover, slip, dan kondisi transien memerlukan model lebih rinci.', 'Separation does not make two-phase flow simple: local distribution, droplet carryover, slip, and transients require more detailed models.') ] },
      { heading: tx('Turbin-generator dan kondensor', 'Turbine-generator and condenser'), body: [tx('Turbin mengubah sebagian penurunan entalpi uap menjadi kerja poros. Generator mengubah kerja poros menjadi daya listrik.', 'The turbine converts part of the steam enthalpy drop into shaft work. The generator converts shaft work into electrical power.'), tx('Kondensor membuang panas dari uap buang dan menghasilkan kondensat untuk siklus air. Sistem penolak panas membuang energi ke lingkungan.', 'The condenser removes heat from exhaust steam and produces condensate for the water cycle. A heat-rejection system transfers energy to the environment.') ] },
      { heading: tx('Feedwater dan recirculation', 'Feedwater and recirculation'), body: [tx('Feedwater mengembalikan massa air ke bejana. Sirkulasi memengaruhi distribusi aliran melalui teras dan kondisi termohidraulik.', 'Feedwater returns water mass to the vessel. Circulation affects flow distribution through the core and thermal-hydraulic conditions.'), tx('Simulator v3.2 menggunakan indeks feedwater dan aliran dua pompa resirkulasi tanpa kurva pompa, pressure-drop jaringan, atau model kanal bahan bakar.', 'The v3.2 simulator uses feedwater and two-pump recirculation indices without pump curves, network pressure-drop, or fuel-channel models.') ] },
    ], takeaway: tx('Setiap komponen merupakan bagian dari neraca massa dan energi siklus, bukan kontrol yang berdiri sendiri.', 'Each component contributes to the cycle mass and energy balances; it is not an isolated control.'),
  },
  {
    id: 'fission', number: '03', category: tx('Fisika reaktor', 'Reactor physics'), title: tx('Fisi, neutron, dan reaktivitas', 'Fission, neutrons, and reactivity'),
    intro: tx('Fisi membelah inti berat setelah penyerapan neutron. Fragmen fisi, neutron tambahan, dan energi dilepaskan sehingga reaksi berantai mungkin berlanjut.', 'Fission splits a heavy nucleus after neutron absorption. Fission fragments, additional neutrons, and energy are released, allowing a chain reaction to continue.'),
    sections: [
      { heading: tx('Faktor multiplikasi efektif', 'Effective multiplication factor'), body: [tx('k_eff membandingkan populasi neutron satu generasi dengan generasi sebelumnya setelah produksi, absorpsi, dan kebocoran neutron diperhitungkan.', 'k_eff compares neutron population in one generation with the previous generation after accounting for production, absorption, and leakage.'), tx('Secara konseptual, k_eff = 1 disebut kritis, di bawah 1 subkritis, dan di atas 1 superkritis. Istilah ini adalah definisi fisika, bukan instruksi untuk mengatur reaktor.', 'Conceptually, k_eff = 1 is critical, below 1 is subcritical, and above 1 is supercritical. These are physics definitions, not instructions for reactor adjustment.')], formula: tx('ρ = (k_eff − 1) / k_eff', 'ρ = (k_eff − 1) / k_eff'), explanation: tx('ρ adalah reaktivitas. Rumus ini mendefinisikan hubungan reaktivitas terhadap faktor multiplikasi efektif.', 'ρ is reactivity. This equation defines the relationship between reactivity and the effective multiplication factor.'), tag: 'theory' },
      { heading: tx('Neutron prompt dan delayed', 'Prompt and delayed neutrons'), body: [tx('Neutron prompt dilepaskan hampir seketika dalam proses fisi. Neutron delayed muncul kemudian dari peluruhan prekursor produk fisi tertentu.', 'Prompt neutrons are released almost immediately during fission. Delayed neutrons appear later from the decay of certain fission-product precursors.'), tx('Fraksi neutron tertunda lebih kecil, tetapi waktu kemunculannya memengaruhi dinamika populasi neutron. Model point kinetics mengelompokkan prekursor ke beberapa grup.', 'The delayed fraction is smaller, but its timing affects neutron-population dynamics. Point-kinetics models group precursors into several groups.') ] },
    ], takeaway: tx('Reaktivitas adalah ukuran penting dalam fisika reaktor; nilai desain dan parameter kinetika tidak dimodelkan di game.', 'Reactivity is a key reactor-physics quantity; design values and kinetics parameters are not modeled by the game.'),
  },
  {
    id: 'kinetics', number: '04', category: tx('Persamaan teori', 'Theory equations'), title: tx('Point kinetics', 'Point kinetics'),
    intro: tx('Point kinetics menggambarkan dinamika populasi neutron rata-rata dan prekursor delayed dengan asumsi bentuk distribusi spasial neutron tidak berubah signifikan selama transien yang ditinjau.', 'Point kinetics describes average neutron population and delayed precursor dynamics, assuming the spatial neutron distribution does not change significantly during the transient of interest.'),
    sections: [
      { heading: tx('Persamaan kinetika titik', 'Point-kinetics equations'), body: [tx('n adalah populasi neutron relatif; C_i konsentrasi prekursor grup ke-i; β_i fraksi neutron delayed grup; λ_i konstanta peluruhan; Λ waktu generasi prompt; dan ρ reaktivitas.', 'n is relative neutron population; C_i is the precursor concentration for group i; β_i is the delayed-neutron fraction; λ_i is the decay constant; Λ is prompt generation time; and ρ is reactivity.'), tx('Persamaan ini bersifat umum dan menjadi dasar studi dinamika neutron sederhana. Model ruang penuh membutuhkan solusi neutron transport/diffusion dan data nuklir.', 'These general equations form a basis for simple neutron-dynamics studies. A spatial model requires neutron transport/diffusion solutions and nuclear data.')], formula: tx('dn/dt = [(ρ − β_eff)/Λ] n + Σ λ_i C_i\ndC_i/dt = (β_i/Λ) n − λ_i C_i\nβ_eff = Σ β_i', 'dn/dt = [(ρ − β_eff)/Λ] n + Σ λ_i C_i\ndC_i/dt = (β_i/Λ) n − λ_i C_i\nβ_eff = Σ β_i'), explanation: tx('Persamaan teori umum. Tidak digunakan oleh engine game v3.2; engine game menggunakan indeks target dan respons orde-satu sintetis.', 'General theory. It is not used by the v3.2 game engine; the game uses target indices and synthetic first-order responses.'), tag: 'theory' },
      { heading: tx('Asumsi dan batas', 'Assumptions and limits'), body: [tx('Pendekatan titik dapat kurang memadai ketika distribusi daya berubah spasial, umpan balik lokal dominan, atau kondisi tidak sesuai asumsi kinetika titik.', 'The point approximation may be inadequate when power distribution changes spatially, local feedback dominates, or conditions violate point-kinetics assumptions.'), tx('Simulator pendidikan ini tidak menyelesaikan persamaan neutron, tidak menghitung β_eff atau Λ, dan tidak memprediksi distribusi daya teras.', 'This educational simulator does not solve neutron equations, calculate β_eff or Λ, or predict core power distribution.') ] },
    ], takeaway: tx('Jangan menyamakan persamaan teori point kinetics dengan rumus indeks sederhana yang digunakan simulator.', 'Do not confuse point-kinetics theory with the simple index equations used by the simulator.'),
  },
  {
    id: 'thermohydraulics', number: '05', category: tx('Termohidraulika', 'Thermal hydraulics'), title: tx('Neraca massa, energi, dan aliran dua fase', 'Mass, energy, and two-phase flow'),
    intro: tx('Termohidraulika menghubungkan massa fluida, energi, tekanan, temperatur, dan perubahan fase. Persamaan berikut adalah bentuk konservasi umum dengan batas kendali yang ditentukan secara eksplisit.', 'Thermal hydraulics links fluid mass, energy, pressure, temperature, and phase change. The following are general conservation equations for a clearly defined control volume.'),
    sections: [
      { heading: tx('Neraca massa control volume', 'Control-volume mass balance'), body: [tx('Laju perubahan massa di dalam volume kendali sama dengan laju massa masuk dikurangi laju massa keluar. Untuk beberapa inlet dan outlet, semua aliran dijumlahkan.', 'The rate of mass change inside a control volume equals mass inflow minus mass outflow. For multiple inlets and outlets, all streams are summed.')], formula: tx('dM_CV/dt = Σṁ_in − Σṁ_out', 'dM_CV/dt = Σṁ_in − Σṁ_out'), explanation: tx('M_CV adalah massa dalam volume kendali (kg); ṁ adalah laju aliran massa (kg/s).', 'M_CV is the mass inside the control volume (kg); ṁ is mass flow rate (kg/s).'), tag: 'theory' },
      { heading: tx('Neraca energi', 'Energy balance'), body: [tx('Perubahan energi tersimpan dipengaruhi perpindahan panas, kerja, dan energi yang dibawa aliran massa. Bentuk lengkap dapat mencakup energi internal, kinetik, dan potensial.', 'Stored-energy change is influenced by heat transfer, work, and energy carried by mass flows. A complete form may include internal, kinetic, and potential energy.')], formula: tx('dE_CV/dt = Q̇ − Ẇ + Σṁ_in h_in − Σṁ_out h_out', 'dE_CV/dt = Q̇ − Ẇ + Σṁ_in h_in − Σṁ_out h_out'), explanation: tx('Q̇ adalah panas masuk; Ẇ adalah kerja keluar; h adalah entalpi spesifik. Tanda bergantung pada konvensi sistem.', 'Q̇ is heat input; Ẇ is work output; h is specific enthalpy. Sign convention depends on the system definition.'), tag: 'theory' },
      { heading: tx('Steam quality dan void fraction', 'Steam quality and void fraction'), body: [tx('Steam quality x adalah fraksi massa uap dalam campuran dua fase. Void fraction α adalah fraksi volume yang ditempati fase uap. Keduanya bukan besaran yang sama.', 'Steam quality x is the vapor mass fraction in a two-phase mixture. Void fraction α is the volume fraction occupied by vapor. They are not the same quantity.'), tx('Hubungan antara keduanya bergantung pada densitas fase dan slip velocity. Model homogen sederhana mengasumsikan kecepatan fase sama; kondisi nyata dapat memerlukan model aliran terpisah.', 'Their relationship depends on phase densities and slip velocity. A simple homogeneous model assumes equal phase velocities; real conditions may require separated-flow models.')], formula: tx('x = m_g / (m_g + m_l)\nα = V_g / (V_g + V_l)', 'x = m_g / (m_g + m_l)\nα = V_g / (V_g + V_l)'), explanation: tx('m_g/m_l adalah massa fase uap/cair; V_g/V_l adalah volume fase uap/cair.', 'm_g/m_l are vapor/liquid masses; V_g/V_l are vapor/liquid volumes.'), tag: 'theory' },
      { heading: tx('Densitas campuran homogen', 'Homogeneous mixture density'), body: [tx('Sebagai ilustrasi, densitas campuran berdasarkan volume dapat ditulis sebagai penjumlahan kontribusi tiap fase. Persamaan ini tidak menangkap slip, pola aliran, atau stratifikasi.', 'As an illustration, mixture density by volume can be expressed as the sum of each phase contribution. This equation does not capture slip, flow regimes, or stratification.')], formula: tx('ρ_mix = α ρ_g + (1 − α) ρ_l', 'ρ_mix = α ρ_g + (1 − α) ρ_l'), explanation: tx('ρ_g dan ρ_l adalah densitas fase gas/uap dan cair. Bentuk ini merupakan hubungan campuran sederhana.', 'ρ_g and ρ_l are vapor and liquid phase densities. This is a simplified mixture relation.'), tag: 'theory' },
    ], takeaway: tx('Neraca massa dan energi adalah kerangka konservasi. Prediksi kuantitatif memerlukan properti fluida, geometri, kondisi batas, dan model aliran yang sesuai.', 'Mass and energy balances are conservation frameworks. Quantitative prediction requires fluid properties, geometry, boundary conditions, and appropriate flow models.'),
  },
  {
    id: 'heat', number: '06', category: tx('Perpindahan panas', 'Heat transfer'), title: tx('Perpindahan panas dan termodinamika', 'Heat transfer and thermodynamics'),
    intro: tx('Panas berpindah melalui konduksi, konveksi, dan radiasi. Dalam sistem reaktor berpendingin air, konduksi bahan bakar dan konveksi ke coolant merupakan fenomena utama yang dipelajari.', 'Heat transfers through conduction, convection, and radiation. In water-cooled reactor systems, fuel conduction and convection to coolant are key phenomena.'),
    sections: [
      { heading: tx('Konduksi Fourier', 'Fourier conduction law'), body: [tx('Hukum Fourier menyatakan fluks panas sebanding dengan gradien temperatur dan bergerak ke arah temperatur yang lebih rendah.', 'Fourier law states that heat flux is proportional to the temperature gradient and directed toward lower temperature.')], formula: tx('q″ = −k ∇T', 'q″ = −k ∇T'), explanation: tx('q″ fluks panas (W/m²); k konduktivitas termal (W/m·K); ∇T gradien temperatur (K/m).', 'q″ is heat flux (W/m²); k is thermal conductivity (W/m·K); ∇T is temperature gradient (K/m).'), tag: 'theory' },
      { heading: tx('Konveksi Newton', 'Newton cooling relation'), body: [tx('Hubungan konveksi sederhana menyatakan panas yang berpindah sebagai fungsi koefisien perpindahan panas, luas permukaan, dan beda temperatur antara permukaan dengan bulk fluid.', 'A simple convection relation expresses heat transfer as a function of heat-transfer coefficient, surface area, and temperature difference between the surface and bulk fluid.')], formula: tx('Q̇ = h A (T_s − T_∞)', 'Q̇ = h A (T_s − T_∞)'), explanation: tx('h koefisien konveksi (W/m²·K); A luas area (m²); T_s temperatur permukaan dan T∞ temperatur fluida bulk.', 'h is the convection coefficient (W/m²·K); A is area (m²); T_s is surface temperature and T∞ is bulk-fluid temperature.'), tag: 'theory' },
      { heading: tx('Panas peluruhan', 'Decay heat'), body: [tx('Setelah reaksi berantai dihentikan, produk fisi dan aktinida tetap melepaskan panas akibat peluruhan radioaktif. Besarnya berubah terhadap waktu dan komposisi riwayat operasi.', 'After the chain reaction is stopped, fission products and actinides continue to release heat through radioactive decay. Its magnitude changes with time and irradiation history.'), tx('Engine game hanya menjaga indeks termal sederhana setelah SCRAM. Ia tidak menghitung spektrum radionuklida, kurva decay heat, atau inventori bahan bakar.', 'The game engine only maintains a simplified thermal index after SCRAM. It does not calculate radionuclide spectra, decay-heat curves, or fuel inventory.') ] },
    ], takeaway: tx('Temperatur tidak sama dengan energi tersimpan. Model termal memerlukan kapasitas panas, geometri, konduktivitas, perpindahan panas, dan kondisi fluida.', 'Temperature is not the same as stored energy. Thermal models require heat capacity, geometry, conductivity, heat transfer, and fluid conditions.'),
  },
  {
    id: 'cycle', number: '07', category: tx('Siklus daya', 'Power cycle'), title: tx('Turbin, generator, dan efisiensi', 'Turbine, generator, and efficiency'),
    intro: tx('BWR mengubah energi termal menjadi listrik melalui ekspansi uap pada turbin, kerja poros, dan konversi elektromagnetik di generator.', 'A BWR converts thermal energy into electricity through steam expansion in a turbine, shaft work, and electromagnetic conversion in a generator.'),
    sections: [
      { heading: tx('Efisiensi termal', 'Thermal efficiency'), body: [tx('Efisiensi termal siklus didefinisikan sebagai kerja bersih siklus dibagi panas yang masuk. Batas sistem menentukan apakah energi pompa dan beban bantu dihitung.', 'Cycle thermal efficiency is net cycle work divided by heat input. The system boundary determines whether pump and auxiliary loads are included.')], formula: tx('η_th = Ẇ_net / Q̇_in', 'η_th = Ẇ_net / Q̇_in'), explanation: tx('Rasio tak berdimensi. Nilai aktual memerlukan keadaan termodinamika, entalpi, efisiensi turbin, generator, dan beban bantu.', 'A dimensionless ratio. Actual values require thermodynamic states, enthalpies, turbine/generator efficiencies, and auxiliary loads.'), tag: 'theory' },
      { heading: tx('Perbedaan daya termal dan listrik', 'Thermal versus electrical power'), body: [tx('Daya termal terkait laju pelepasan panas di reaktor. Daya listrik adalah keluaran generator setelah rugi-rugi dan kebutuhan internal.', 'Thermal power relates to the reactor heat-release rate. Electrical power is generator output after losses and internal loads.'), tx('Simulator v3.2 menggunakan grid index sebagai proxy visual. Tidak ada perhitungan entalpi uap, efisiensi stage turbin, atau generator elektromagnetik.', 'The v3.2 simulator uses a grid index as a visual proxy. It does not calculate steam enthalpy, turbine-stage efficiency, or electromagnetic generator behavior.') ] },
    ], takeaway: tx('Daya, energi, dan efisiensi adalah besaran berbeda. Jangan membaca indeks output game sebagai MW atau efisiensi fasilitas.', 'Power, energy, and efficiency are different quantities. Do not read the game output index as MW or facility efficiency.'),
  },
  {
    id: 'game-model', number: '08', category: tx('Engine simulator', 'Simulator engine'), title: tx('Rumus yang benar-benar dipakai game', 'Equations actually used by the game'),
    intro: tx('Engine v3.2 sengaja memakai model indeks tanpa satuan dan respons orde-satu agar ringan di browser. Rumus ini adalah mekanika permainan, bukan persamaan fisik tervalidasi.', 'The v3.2 engine deliberately uses dimensionless indices and first-order responses to stay lightweight in a browser. These equations are game mechanics, not validated physical equations.'),
    sections: [
      { heading: tx('Target indeks daya', 'Power-index target'), body: [tx('Target daya dihitung dari indeks kendali dan sirkulasi. Nilai kontrol adalah slider permainan, bukan posisi batang atau kecepatan pompa sesungguhnya.', 'The power target is computed from control and circulation indices. Control values are game sliders, not actual rod positions or pump speeds.')], formula: tx('P_target = clamp[70 + 0.92(50 − R) + 0.34(C − 65), 2, 138]', 'P_target = clamp[70 + 0.92(50 − R) + 0.34(C − 65), 2, 138]'), explanation: tx('R indeks rod; C indeks sirkulasi. Koefisien dipilih untuk respons visual dan tidak memiliki unit reaktor.', 'R is the rod index; C is the circulation index. Coefficients are chosen for visual response and have no reactor units.'), tag: 'game' },
      { heading: tx('Respons orde-satu', 'First-order response'), body: [tx('Nilai saat ini bergerak menuju target dengan pendekatan relaksasi orde-satu. Besaran dt adalah langkah waktu numerik game.', 'The current value moves toward its target using a first-order relaxation. dt is the game numerical time step.')], formula: tx('P(t + dt) = P(t) + [P_target − P(t)] · 0.13 · dt', 'P(t + dt) = P(t) + [P_target − P(t)] · 0.13 · dt'), explanation: tx('Persamaan diskrit yang dipakai di model perangkat lunak. Tidak setara dengan point kinetics.', 'A discrete equation used by the software model. It is not equivalent to point kinetics.'), tag: 'game' },
      { heading: tx('Neraca inventori air sintetis', 'Synthetic water inventory balance'), body: [tx('Perubahan indeks inventori mengikuti selisih indeks feedwater dan steam. Tidak ada massa dalam kg, tekanan dalam MPa, atau kurva fase.', 'The water-inventory index changes according to the difference between feedwater and steam indices. There is no mass in kg, pressure in MPa, or phase-property curve.')], formula: tx('W(t + dt) = W(t) + 0.038 · (FW − S) · dt', 'W(t + dt) = W(t) + 0.038 · (FW − S) · dt'), explanation: tx('W inventori; FW indeks feedwater; S indeks uap. Faktor 0.038 adalah koefisien game.', 'W is inventory; FW is feedwater index; S is steam index. The 0.038 factor is a game coefficient.'), tag: 'game' },
      { heading: tx('Indeks tekanan dan termal', 'Pressure and thermal indices'), body: [tx('Tekanan mengikuti indeks ketidakseimbangan uap dan aliran turbin. Indeks termal mengikuti relaksasi menuju target yang bergantung pada indeks daya dan inventori.', 'Pressure follows a steam/turbine-flow imbalance index. Thermal index relaxes toward a target depending on power and inventory indices.'), tx('Faults hanya mengubah koefisien sintetis, dan sensor fault mengubah pembacaan tampilan tanpa mengubah state model. Semua ambang kegagalan hanya ambang game.', 'Faults only modify synthetic coefficients, and sensor faults change displayed readings without changing model state. All failure limits are game-only thresholds.') ] },
    ], takeaway: tx('Rumus simulator ditampilkan transparan untuk debugging dan pembelajaran software, bukan untuk prediksi reaktor nyata.', 'Simulator equations are exposed for software-learning and debugging transparency, not for real-reactor prediction.'),
  },
  {
    id: 'safety-vv', number: '09', category: tx('Keselamatan & model', 'Safety & modeling'), title: tx('Defense in depth, verifikasi, dan validasi', 'Defense in depth, verification, and validation'),
    intro: tx('Keselamatan nuklir bergantung pada berlapis-lapis fungsi pencegahan, pengendalian, mitigasi, dan perlindungan. Simulator browser sederhana tidak menggantikan analisis keselamatan atau sistem proteksi.', 'Nuclear safety relies on layered prevention, control, mitigation, and protection functions. A simple browser simulator does not replace safety analysis or protection systems.'),
    sections: [
      { heading: tx('Defense in depth', 'Defense in depth'), body: [tx('Konsep defense in depth menghindari ketergantungan pada satu penghalang atau satu fungsi. Beberapa lapisan dirancang untuk mencegah kondisi tidak diinginkan dan membatasi konsekuensi bila lapisan lain tidak bekerja.', 'Defense in depth avoids reliance on a single barrier or function. Multiple layers are designed to prevent unwanted conditions and limit consequences if another layer does not perform.'), tx('Halaman ini hanya menjelaskan prinsip arsitektur keselamatan secara umum. Tidak memuat langkah respons operator, nilai setpoint, urutan tindakan, atau cara menonaktifkan proteksi.', 'This page only explains general safety architecture. It does not provide operator response steps, setpoints, action sequences, or ways to disable protection.') ] },
      { heading: tx('Verifikasi versus validasi', 'Verification versus validation'), body: [tx('Verifikasi bertanya apakah implementasi perangkat lunak sesuai spesifikasi dan persamaan yang ditulis. Contoh: uji determinisme seed, batas nilai, dan regresi fungsi.', 'Verification asks whether software implementation matches its specification and written equations. Examples include deterministic seeds, value bounds, and regression tests.'), tx('Validasi bertanya apakah model cukup merepresentasikan fenomena nyata untuk tujuan tertentu. Validasi memerlukan data acuan, ketidakpastian, evaluasi pakar, dan batas penggunaan yang ditetapkan.', 'Validation asks whether a model represents real phenomena adequately for a given purpose. It requires reference data, uncertainty analysis, expert review, and defined applicability limits.') ] },
    ], takeaway: tx('Uji software yang lulus bukan bukti model fisik tervalidasi atau aman untuk operasi.', 'Passing software tests does not validate the physical model or make it safe for operation.'),
  },
  {
    id: 'xenon', number: '10', category: tx('Dinamik nuklir', 'Nuclear dynamics'), title: tx('Iodine-135 dan Xenon-135', 'Iodine-135 and Xenon-135'),
    intro: tx('Xenon-135 adalah penyerap neutron kuat yang berubah mengikuti sejarah daya. Setelah penurunan daya atau shutdown, Xe-135 dapat terus bertambah sementara karena I-135 yang tersisa masih meluruh menjadi Xe-135.', 'Xenon-135 is a strong neutron absorber whose inventory depends on power history. After a power reduction or shutdown, Xe-135 can continue increasing temporarily because the remaining I-135 decays into Xe-135.'),
    sections: [
      { heading: tx('Rantai peluruhan dan penyerapan', 'Decay and absorption chain'), body: [tx('I-135 terbentuk sebagai produk fisi dan meluruh menjadi Xe-135. Xe-135 kemudian berkurang melalui peluruhan radioaktif dan penyerapan neutron. Ketika daya berubah, laju produksi dan laju burn-up tidak langsung mencapai keseimbangan baru.', 'I-135 is produced as a fission product and decays into Xe-135. Xe-135 is then removed by radioactive decay and neutron absorption. When power changes, production and burn-up rates do not immediately reach a new equilibrium.'), tx('Itulah sebabnya perubahan daya memiliki memori waktu. Responsnya bergantung pada sejarah operasi dan komposisi isotop, bukan hanya nilai daya sesaat.', 'This gives power changes a time-history effect. The response depends on operating history and isotope inventories, not only instantaneous power.')], formula: tx(`dI/dt = γI·F − λI·I\ndX/dt = γX·F + λI·I − λX·X − σX·φ·X`, `dI/dt = γI·F − λI·I\ndX/dt = γX·F + λI·I − λX·X − σX·φ·X`), explanation: tx('Persamaan neraca nuklida konseptual. I dan X adalah inventori I-135 dan Xe-135; F mewakili laju fisi; λ adalah konstanta peluruhan; φ adalah fluks neutron. Model penuh memerlukan data nuklir dan fluks.', 'Conceptual nuclide-balance equations. I and X are I-135 and Xe-135 inventories; F represents fission rate; λ denotes decay constants; φ is neutron flux. A full model requires nuclear data and neutron flux.'), tag: 'theory' },
      { heading: tx('Xenon pada engine game', 'Xenon in the game engine'), body: [tx('Engine v3.2 menggunakan dua inventori ternormalisasi dan waktu model yang dipercepat. Setelah daya turun, produksi xenon dari iodine dapat sementara lebih besar daripada laju penghilangan xenon. Penumpukan ini meningkatkan inhibition index dan membuat model lebih sulit kembali ke daya awal.', 'The v3.2 engine uses two normalized inventories and an accelerated model clock. After power falls, xenon production from iodine can temporarily exceed xenon removal. This buildup raises the inhibition index and makes the model harder to return to its previous power.'), tx('Koefisien dan waktu game tidak berasal dari parameter teras BWR tertentu. Kurva ini hanya menggambarkan bentuk keterlambatan secara kualitatif.', 'Game coefficients and timing are not taken from a specific BWR core. The curve illustrates delayed behavior qualitatively only.')], formula: tx(`I' = 0.025 p − 0.08 I\nX' = 0.08 I − (0.025 + 0.035 p) X`, `I' = 0.025 p − 0.08 I\nX' = 0.08 I − (0.025 + 0.035 p) X`), explanation: tx('Proxy sintetis engine v3.2. p adalah indeks daya ternormalisasi; turunan terhadap jam simulasi. Bukan konstanta nuklir atau prediksi waktu xenon nyata.', 'Synthetic v3.2 engine proxy. p is normalized power index; derivatives are with respect to simulated hours. These are not nuclear constants or a prediction of real xenon timing.'), tag: 'game' },
    ], takeaway: tx('Xenon menambahkan memori waktu dan menunjukkan mengapa respons reaktor tidak hanya ditentukan oleh keadaan sesaat.', 'Xenon adds time-history effects and shows why reactor response is not determined by instantaneous conditions alone.'),
  },
  {
    id: 'period', number: '11', category: tx('Dinamik nuklir', 'Nuclear dynamics'), title: tx('Neutron tertunda dan periode reaktor', 'Delayed neutrons and reactor period'),
    intro: tx('Periode reaktor menggambarkan skala waktu perubahan populasi neutron atau daya. Neutron tertunda membuat dinamika neutron dapat merespons pada skala waktu yang lebih panjang dibanding respons prompt saja.', 'Reactor period describes the time scale of neutron-population or power change. Delayed neutrons allow neutron dynamics to respond on longer time scales than prompt response alone.'),
    sections: [
      { heading: tx('Definisi periode', 'Period definition'), body: [tx('Untuk pertumbuhan eksponensial ideal n(t) = n₀e^(t/T), T adalah periode e-folding: waktu yang diperlukan populasi untuk berubah dengan faktor e pada model eksponensial tersebut.', 'For ideal exponential growth n(t) = n₀e^(t/T), T is the e-folding period: the time required for the population to change by a factor of e under that exponential model.'), tx('Dalam sistem riil, estimator periode dari data noisy perlu filtering, validasi kanal, dan interpretasi rentang pengukuran. Satu pembacaan singkat tidak cukup untuk menyimpulkan keadaan reaktor.', 'In real systems, period estimates from noisy data require filtering, channel validation, and interpretation of the measurement range. A single short reading is not enough to infer reactor condition.')], formula: tx('T = 1 / (d ln n / dt)', 'T = 1 / (d ln n / dt)'), explanation: tx('Definisi matematis umum periode eksponensial. Simulator menampilkan period proxy dari kemiringan log indeks daya, bukan kanal periode nuklir.', 'General mathematical definition of exponential period. The simulator displays a period proxy from the log-slope of its power index, not a nuclear period channel.'), tag: 'theory' },
      { heading: tx('Neutron tertunda', 'Delayed neutrons'), body: [tx('Model point kinetics menggabungkan populasi neutron dengan satu atau beberapa kelompok prekursor delayed. Waktu peluruhan prekursor memberi respons dinamis tambahan.', 'Point-kinetics models couple neutron population with one or more delayed-precursor groups. Precursor decay times add dynamic response.'), tx('Engine game memakai satu indeks lag untuk memberi inersia pada perubahan daya. Engine tidak menyelesaikan sistem persamaan point kinetics dan tidak menggunakan parameter β_eff atau Λ desain.', 'The game engine uses one lag index to add inertia to power changes. It does not solve point-kinetics equations or use design β_eff or Λ parameters.')], formula: tx('dn/dt = [(ρ − βeff)/Λ] n + Σ λiCi', 'dn/dt = [(ρ − βeff)/Λ] n + Σ λiCi'), explanation: tx('Teori umum. Engine v3.2 hanya menampilkan dinamika tertunda secara pedagogis.', 'General theory. The v3.2 engine only represents delayed dynamics pedagogically.'), tag: 'theory' },
    ], takeaway: tx('Periode adalah informasi tren waktu, bukan sekadar angka daya; ketidakpastian dan kualitas pengukuran juga penting.', 'Period is time-trend information, not simply a power number; measurement quality and uncertainty matter too.'),
  },
  {
    id: 'level-swell', number: '12', category: tx('Instrumentasi', 'Instrumentation'), title: tx('Level swell, shrink, dan sensor yang menipu', 'Level swell, shrink, and misleading sensors'),
    intro: tx('Level instrumen pada bejana dua fase tidak selalu sama dengan inventori massa air. Perubahan tekanan dan fraksi uap dapat mengubah volume campuran sehingga indikasi level berubah tanpa perubahan inventori yang sebanding.', 'An instrument level indication in a two-phase vessel is not always equal to liquid mass inventory. Pressure and vapor fraction changes can alter mixture volume, so indicated level can change without a proportional inventory change.'),
    sections: [
      { heading: tx('Swell dan shrink', 'Swell and shrink'), body: [tx('Perubahan tekanan dapat mengubah ukuran gelembung dan distribusi void. Ketika void mengembang, level campuran dapat tampak naik; ketika void menyusut, level campuran dapat tampak turun. Respons aktual tergantung desain, kondisi, lokasi instrument tap, dan dinamika dua fase.', 'Pressure changes can alter bubble size and void distribution. When voids expand, mixture level can appear to rise; when voids collapse, mixture level can appear to fall. Actual response depends on design, conditions, instrument-tap location, and two-phase dynamics.'), tx('Karena itu, indikasi level harus dibaca bersama parameter independen lain dan pemahaman ketidakpastian sensor. Simulator memisahkan inventory index tersembunyi dari indicated-level proxy agar perbedaannya dapat dipelajari.', 'Therefore, level indication should be considered alongside independent parameters and sensor uncertainty. The simulator separates hidden inventory index from indicated-level proxy to make the distinction visible.')], formula: tx('L_ind = L_inventory + k_v·α + k_p·max(0, −dp/dt)', 'L_ind = L_inventory + k_v·α + k_p·max(0, −dp/dt)'), explanation: tx('Bentuk pedagogis untuk hubungan indikasi dan swell. k_v, k_p, α, dan p bukan parameter instrumen BWR nyata.', 'A pedagogical form for indication and swell. k_v, k_p, α, and p are not real BWR instrument parameters.'), tag: 'game' },
      { heading: tx('Instrument freeze dan bias', 'Instrument freeze and bias'), body: [tx('Sensor dapat mengalami bias, drift, noise, atau freeze. Indikasi yang tampak stabil belum tentu benar; membandingkan kanal berbeda dan tren yang konsisten adalah bagian penting dari literasi instrumentasi.', 'Sensors can experience bias, drift, noise, or freeze. A stable-looking indication is not necessarily correct; comparing independent channels and consistent trends is an important part of instrumentation literacy.'), tx('Game memodelkan satu kanal yang tertahan atau bergeser. Gangguan tersebut tidak mewakili probabilitas atau mode kegagalan perangkat tertentu.', 'The game models one channel as frozen or biased. These disturbances do not represent the probability or failure modes of any particular device.') ] },
    ], takeaway: tx('Bedakan keadaan proses, nilai yang ditampilkan instrumen, dan tingkat keyakinan terhadap pengukuran.', 'Distinguish process state, instrument indication, and confidence in the measurement.'),
  },
  {
    id: 'flow-map', number: '13', category: tx('Termohidraulik', 'Thermal hydraulics'), title: tx('Peta daya–aliran dan batas pendidihan', 'Power–flow map and boiling limits'),
    intro: tx('Daya dan aliran pendingin harus dipahami bersama. Besaran termal lokal tidak ditentukan oleh satu rasio global saja; distribusi kanal, kualitas uap, geometri, dan kondisi transien turut berpengaruh.', 'Power and coolant flow must be understood together. Local thermal conditions are not determined by one global ratio; channel distribution, steam quality, geometry, and transient conditions also matter.'),
    sections: [
      { heading: tx('Critical heat flux dan boiling transition', 'Critical heat flux and boiling transition'), body: [tx('Critical heat flux (CHF) merujuk pada kondisi batas perpindahan panas pendidihan ketika mekanisme pembasahan permukaan dapat berubah. Dalam analisis BWR, rasio critical power dan minimum critical power ratio (MCPR) digunakan untuk mengkarakterisasi margin terhadap boiling transition pada bundel bahan bakar.', 'Critical heat flux (CHF) refers to a boiling heat-transfer limit at which surface wetting behavior can change. In BWR analysis, critical power ratio and minimum critical power ratio (MCPR) characterize margin to boiling transition in fuel bundles.'), tx('MCPR bergantung pada bundle, kondisi lokal, distribusi daya, aliran, kualitas uap, dan metodologi desain. Nilai aktual dan batas operasi tidak disediakan oleh simulator ini.', 'MCPR depends on bundle design, local conditions, power distribution, flow, steam quality, and design methodology. Actual values and operating limits are not provided by this simulator.')], formula: tx(`CPR = P_critical / P_bundle\nMCPR = min(CPR_bundle)`, `CPR = P_critical / P_bundle\nMCPR = min(CPR_bundle)`), explanation: tx('Definisi konseptual. Bukan rumus hitung lengkap untuk menentukan batas operasi; tidak ada MCPR numerik di game.', 'Conceptual definition. Not a complete calculation for determining operating limits; the game has no numerical MCPR.'), tag: 'theory' },
      { heading: tx('Peta daya–aliran game', 'Game power–flow map'), body: [tx('v3.2 menampilkan flow/power ratio dan boiling-margin proxy. Zona peringatan dibuat dari indeks global sederhana untuk mengajarkan bahwa kenaikan daya tanpa perubahan aliran yang sepadan dapat mengurangi margin model.', 'v3.2 displays a flow/power ratio and a boiling-margin proxy. Warning zones are based on a simple global index to teach that increasing power without a corresponding flow change can reduce model margin.'), tx('Peta ini tidak menghitung aliran kanal paralel, dryout, void distribution axial/radial, CHF correlation, atau CPR bundle. Ia tidak boleh dibaca sebagai peta batas aman BWR.', 'This map does not calculate parallel-channel flow, dryout, axial/radial void distribution, CHF correlations, or bundle CPR. It must not be read as a BWR safe operating map.')], formula: tx(`R_flow = F_circulation / max(P_index, ε)\nM_game = clamp(100 − a·P − b·flowPenalty, 0, 100)`, `R_flow = F_circulation / max(P_index, ε)\nM_game = clamp(100 − a·P − b·flowPenalty, 0, 100)`), explanation: tx('Proxy tanpa satuan pada engine. Koefisien a dan b dipilih untuk dinamika game.', 'Dimensionless engine proxy. Coefficients a and b are chosen for game dynamics.'), tag: 'game' },
    ], takeaway: tx('Peta daya–aliran adalah alat intuisi; margin termal nyata memerlukan analisis kanal dan bundel tervalidasi.', 'A power–flow map is an intuition aid; real thermal margin requires validated channel and bundle analysis.'),
  },
  {
    id: 'feedwater', number: '14', category: tx('Transien', 'Transients'), title: tx('Suhu feedwater dan umpan balik void', 'Feedwater temperature and void feedback'),
    intro: tx('Feedwater temperature ikut memengaruhi entalpi air masuk dan keadaan termohidraulik di bejana. Dampaknya pada reaktivitas bergantung desain teras serta kondisi operasi.', 'Feedwater temperature affects inlet-water enthalpy and vessel thermal-hydraulic conditions. Its reactivity effect depends on core design and operating conditions.'),
    sections: [
      { heading: tx('Perubahan temperatur masuk', 'Inlet temperature changes'), body: [tx('Gangguan pemanas feedwater dapat mengubah temperatur air masuk. Dalam analisis transient tertentu untuk desain ABWR yang diteliti NRC, penurunan temperatur feedwater dikaitkan dengan collapse void, perubahan reaktivitas, dan respons level. Ini adalah hasil analisis kasus desain tertentu, bukan aturan universal untuk semua BWR.', 'A feedwater-heater disturbance can change inlet-water temperature. In a specific NRC analysis of an ABWR design transient, a feedwater-temperature decrease was associated with void collapse, a reactivity change, and level response. This is a design-specific analysis, not a universal rule for every BWR.')], formula: tx('ΔT_feedwater → Δvoid → Δmoderation / Δreactivity', 'ΔT_feedwater → Δvoid → Δmoderation / Δreactivity'), explanation: tx('Rantai sebab-akibat konseptual. Tanda dan besarnya respons memerlukan kondisi teras dan analisis desain.', 'Conceptual causal chain. The sign and magnitude require core conditions and design-specific analysis.') },
      { heading: tx('Proxy v3.2', 'v3.2 proxy'), body: [tx('Engine game mengubah feedwater temperature index melalui gangguan heater dan menambahkan umpan balik kecil pada indeks reaktivitas. Efek ini sengaja dibuat sederhana untuk memunculkan interaksi lambat dengan xenon dan aliran.', 'The game engine changes a feedwater-temperature index through a heater fault and adds a small feedback to the reactivity index. This is deliberately simple to create a slow interaction with xenon and flow.'), tx('Tidak ada persamaan entalpi, densitas jenuh, steam tables, atau model void terkopel yang tervalidasi.', 'There are no enthalpy equations, saturation-density calculations, steam tables, or validated coupled-void model.')], formula: tx('ρ_FW,game = c · max(0, T_ref − T_FW,index)', 'ρ_FW,game = c · max(0, T_ref − T_FW,index)'), explanation: tx('Koefisien c adalah parameter game; indeks temperatur tidak dalam °C.', 'Coefficient c is a game parameter; temperature index is not in °C.'), tag: 'game' },
    ], takeaway: tx('Efek feedwater bersifat terkopel dan design-dependent; jangan menyimpulkan respons universal dari satu skenario.', 'Feedwater effects are coupled and design-dependent; do not infer a universal response from one scenario.'),
  },
  {
    id: 'support-systems', number: '15', category: tx('Sistem penunjang', 'Support systems'), title: tx('Isolasi, pendinginan darurat, listrik, dan kontainmen', 'Isolation, emergency cooling, power, and containment'),
    intro: tx('BWR memiliki sistem operasi dan sistem pendukung dengan fungsi yang berbeda. Nama, redundansi, logika aktuasi, serta konfigurasi sistem sangat bergantung pada desain dan generasi pembangkit.', 'BWRs have operating and support systems with distinct functions. System names, redundancy, actuation logic, and configuration depend strongly on plant design and generation.'),
    sections: [
      { heading: tx('Jalur uap dan MSIV', 'Steam path and MSIV'), body: [tx('Main steam isolation valves (MSIV) merupakan bagian dari konsep isolasi jalur uap utama. Penutupan jalur uap memengaruhi pelepasan uap ke turbin dan dapat mengubah dinamika tekanan serta sistem lain.', 'Main steam isolation valves (MSIVs) are part of the main-steam isolation concept. Isolating the steam path affects steam delivery to the turbine and can change pressure dynamics and other systems.'), tx('Simulator hanya menampilkan katup sebagai state konseptual yang memiliki jeda. Model tidak meniru logika aktuasi atau persyaratan proteksi plant tertentu.', 'The simulator represents the valve as a conceptual state with delay. It does not reproduce actuation logic or protection requirements for any specific plant.') ] },
      { heading: tx('Pendinginan dan pengelolaan panas', 'Cooling and heat management'), body: [tx('Arsitektur BWR dapat mencakup beberapa fungsi emergency core cooling dan residual heat removal. Contoh umum dalam literatur publik mencakup injeksi pendingin, core spray, mode low-pressure coolant injection, dan RHR. Implementasi rinci berbeda antar desain.', 'BWR architectures can include multiple emergency core-cooling and residual-heat-removal functions. Public references describe general examples such as coolant injection, core spray, low-pressure coolant injection modes, and RHR. Detailed implementation differs by design.'), tx('Suppression pool/wetwell dapat menjadi bagian dari konsep pressure-suppression containment pada sejumlah desain BWR. Simulator menggunakan indeks pool dan containment semata-mata untuk menggambarkan akumulasi beban konseptual.', 'A suppression pool/wetwell can be part of pressure-suppression containment in several BWR designs. The simulator uses pool and containment indices only to represent conceptual load accumulation.') ] },
      { heading: tx('Listrik eksternal dan sumber cadangan', 'Offsite and backup power'), body: [tx('Sistem normal dan sebagian sistem pendinginan membutuhkan sumber listrik. Literatur NRC menjelaskan bahwa sumber cadangan onsite seperti generator diesel dapat menyediakan daya bagi fungsi tertentu ketika daya eksternal hilang.', 'Normal systems and some cooling systems require electrical power. NRC public material describes onsite backup sources such as diesel generators supplying power to certain functions when offsite power is lost.'), tx('Engine v3.2 memodelkan blackout, sumber cadangan, dan interlock bus sebagai state boolean dengan jeda waktu. Ini bukan single-line diagram, studi keandalan, atau urutan pemulihan listrik plant.', 'The v3.2 engine models blackout, backup source, and bus interlocks as boolean states with delays. This is not a single-line diagram, reliability study, or plant electrical recovery sequence.') ] },
    ], takeaway: tx('Sistem keselamatan saling bergantung, tetapi konfigurasi dan logika aktual harus dipelajari dari dokumen desain dan regulator yang berwenang.', 'Safety systems are interdependent, but actual configuration and logic must be learned from authoritative design and regulatory documents.'),
  },
  {
    id: 'severity', number: '16', category: tx('Evaluasi kejadian', 'Event assessment'), title: tx('Konsekuensi bertingkat dan INES', 'Graduated consequences and INES'),
    intro: tx('Kondisi abnormal dapat berkembang dari deviasi parameter dan paparan batas yang berlanjut hingga degradasi peralatan atau bahan bakar. Tidak semua kejadian berakhir sebagai ledakan atau kegagalan total.', 'Abnormal conditions can progress from parameter deviations and sustained limit exposure to equipment or fuel degradation. Not every event ends in an explosion or total failure.'),
    sections: [
      { heading: tx('Profil konsekuensi di game', 'Game consequence profile'), body: [tx('v3.2 mengakumulasi exposure model, damage index, fuel leakage indication, dan fuel integrity proxy. Skor konsekuensi 0–5 menunjukkan level progresi di dalam permainan, bukan estimasi konsekuensi radiologis nyata.', 'v3.2 accumulates model exposure, damage index, fuel leakage indication, and fuel-integrity proxy. Its 0–5 consequence score indicates progression within the game, not an estimate of real radiological consequences.'), tx('Pelanggaran batas, SCRAM tidak perlu, instrument failure, dan degradasi berkepanjangan dinilai secara terpisah agar evaluasi tidak hanya berfokus pada akhir simulasi.', 'Limit excursions, unnecessary SCRAM, instrument failures, and sustained degradation are assessed separately so evaluation does not focus only on the simulation ending.') ] },
      { heading: tx('Apa itu INES?', 'What is INES?'), body: [tx('International Nuclear and Radiological Event Scale memiliki tujuh level untuk mengomunikasikan signifikansi kejadian nuklir dan radiologi kepada publik. Skala tersebut bukan sistem klasifikasi darurat dan bukan alat untuk membandingkan kinerja operator atau fasilitas.', 'The International Nuclear and Radiological Event Scale has seven levels for communicating the significance of nuclear and radiological events to the public. It is not an emergency classification system and is not a tool for comparing operator or facility performance.'), tx('Karena itu, game tidak memberikan rating INES otomatis. Profil 0–5 yang ditampilkan adalah rubric internal edukatif dan tidak dapat dikonversi menjadi level INES.', 'Therefore, the game does not assign an automatic INES rating. Its 0–5 profile is an internal educational rubric and cannot be converted to an INES level.') ] },
    ], takeaway: tx('Penilaian kejadian nyata mempertimbangkan metodologi formal dan dampak aktual/potensial; skor permainan tidak boleh disebut rating INES.', 'Real event assessment uses formal methodology and actual/potential consequences; a game score must not be called an INES rating.'),
  },
];

const quiz = [
  { question: tx('Apa ciri utama siklus BWR?', 'What is the defining feature of the BWR cycle?'), options: [tx('Uap untuk turbin dibentuk di dalam bejana reaktor.', 'Turbine steam is generated inside the reactor vessel.'), tx('Menggunakan steam generator terpisah untuk loop sekunder.', 'It uses a separate steam generator for a secondary loop.'), tx('Tidak memiliki kondensor.', 'It has no condenser.')], answer: 0, why: tx('BWR menggunakan siklus langsung: air mendidih di bejana dan uap menggerakkan turbin.', 'A BWR uses a direct cycle: water boils in the vessel and steam drives the turbine.') },
  { question: tx('Apa perbedaan steam quality dan void fraction?', 'What is the difference between steam quality and void fraction?'), options: [tx('Keduanya sama.', 'They are identical.'), tx('Quality adalah fraksi massa uap; void fraction adalah fraksi volume uap.', 'Quality is vapor mass fraction; void fraction is vapor volume fraction.'), tx('Quality hanya untuk cairan.', 'Quality applies only to liquid.')], answer: 1, why: tx('Keduanya berbeda dan relasinya bergantung pada densitas fase serta slip.', 'They differ; their relationship depends on phase densities and slip.') },
  { question: tx('Apa fungsi persamaan neraca massa?', 'What does the mass balance equation describe?'), options: [tx('Perubahan massa sama dengan aliran masuk dikurangi aliran keluar.', 'Mass change equals inflow minus outflow.'), tx('Daya listrik dikurangi rugi generator.', 'Electrical power minus generator losses.'), tx('Perubahan reaktivitas terhadap void.', 'Reactivity change with void.')], answer: 0, why: tx('Ini adalah bentuk konservasi massa pada control volume.', 'This is mass conservation for a control volume.') },
  { question: tx('Apakah rumus indeks game merupakan model point kinetics?', 'Are the game index equations a point-kinetics model?'), options: [tx('Ya, karena sama-sama memakai variabel daya.', 'Yes, because both use a power variable.'), tx('Tidak. Itu proxy sintetis untuk permainan.', 'No. They are synthetic game proxies.'), tx('Ya, dan tervalidasi untuk BWR.', 'Yes, and validated for BWRs.')], answer: 1, why: tx('Engine game tidak menyelesaikan dinamika neutron atau parameter kinetika.', 'The game engine does not solve neutron dynamics or kinetics parameters.') },
  { question: tx('Mengapa Xe-135 dapat meningkat setelah penurunan daya atau shutdown?', 'Why can Xe-135 increase after a power reduction or shutdown?'), options: [tx('I-135 yang tersisa masih meluruh menjadi Xe-135.', 'Remaining I-135 continues to decay into Xe-135.'), tx('Semua neutron berubah menjadi xenon.', 'All neutrons turn into xenon.'), tx('Feedwater berhenti mengalir.', 'Feedwater stops flowing.')], answer: 0, why: tx('Produksi dari peluruhan I-135 berlanjut sementara perubahan laju burn-up Xe terjadi segera.', 'Production from I-135 decay continues while the Xe burn-up rate changes immediately.') },
  { question: tx('Apa arti perbedaan level indikasi dan inventori?', 'What does a difference between indicated level and inventory mean?'), options: [tx('Keduanya selalu identik.', 'They are always identical.'), tx('Efek dua fase atau gangguan instrumen dapat mengubah indikasi.', 'Two-phase effects or instrument faults can alter the indication.'), tx('Sensor menentukan massa air sesungguhnya.', 'The sensor determines the actual water mass.')], answer: 1, why: tx('Level indikasi adalah pengukuran yang dapat dipengaruhi void, tekanan, lokasi instrumen, dan gangguan sensor.', 'Indicated level is a measurement affected by voids, pressure, instrument location, and sensor faults.') },
  { question: tx('Apakah profil konsekuensi game dapat disebut level INES?', 'Can the game consequence profile be called an INES level?'), options: [tx('Ya, karena memakai angka bertingkat.', 'Yes, because it uses numbered levels.'), tx('Tidak; rubric game bukan metodologi INES.', 'No; the game rubric is not the INES methodology.'), tx('Hanya jika simulasi berakhir.', 'Only if the simulation ends.')], answer: 1, why: tx('INES adalah skala komunikasi publik dengan metodologi tersendiri dan bukan skor game.', 'INES is a public communication scale with its own methodology, not a game score.') },
];

export default function LearnPage() {
  const { language, t } = useI18n();
  const [selected, setSelected] = useState('overview');
  const [search, setSearch] = useState('');
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [submitted, setSubmitted] = useState(false);
  const [best, setBest] = useState(() => { try { return Number(localStorage.getItem('bwr-v32-quiz-best') ?? 0); } catch { return 0; } });
  const value = (item: LocaleText) => item[language];
  const filtered = useMemo(() => lessons.filter((lesson) => `${value(lesson.title)} ${value(lesson.category)} ${value(lesson.intro)}`.toLowerCase().includes(search.toLowerCase())), [search, language]);
  const activeLesson = lessons.find((lesson) => lesson.id === selected) ?? lessons[0];
  const score = quiz.reduce((sum, item, index) => sum + (answers[index] === item.answer ? 1 : 0), 0);
  const progress = Object.keys(answers).length;
  const submit = () => {
    setSubmitted(true);
    if (score > best) {
      setBest(score);
      try { localStorage.setItem('bwr-v32-quiz-best', String(score)); } catch { /* private mode */ }
    }
  };
  return (
    <section className="learn-page">
      <div className="page-heading"><div><div className="eyebrow">{t('learnEyebrow')}</div><h1>{t('learnTitle')}</h1><p>{t('learnIntro')}</p></div><div className="learn-counter"><strong>{lessons.length}</strong><span>{language === 'id' ? 'BAB MATERI' : 'LESSONS'}</span></div></div>
      <div className="learn-layout">
        <aside className="lesson-sidebar"><div className="sidebar-boundary"><span className="eyebrow">{t('contents')}</span><label className="search-label"><span>⌕</span><input className="search-input" value={search} onChange={(event) => setSearch(event.target.value)} placeholder={t('searchLessons')}/></label><div className="lesson-list">{filtered.map((lesson) => <button key={lesson.id} className={`lesson-nav ${selected === lesson.id ? 'active' : ''}`} onClick={() => setSelected(lesson.id)}><span className="lesson-number">{lesson.number}</span><span><strong>{value(lesson.title)}</strong><small>{value(lesson.category)}</small></span></button>)}{filtered.length === 0 && <p className="empty-search">{language === 'id' ? 'Materi tidak ditemukan.' : 'No lessons found.'}</p>}</div></div><div className="sidebar-foot"><span>{language === 'id' ? 'Skor kuis terbaik' : 'Best quiz score'}</span><strong>{best}/{quiz.length}</strong></div></aside>
        <article className="lesson-article"><div className="lesson-hero"><span className="lesson-counter">{t('chapter')} {activeLesson.number} / {lessons.length} · {value(activeLesson.category)}</span><h2>{value(activeLesson.title)}</h2><p>{value(activeLesson.intro)}</p></div>
          {activeLesson.sections.map((section, index) => <section className="lesson-section" key={`${activeLesson.id}-${index}`}><div className="section-index">{String(index + 1).padStart(2, '0')}</div><div className="section-content"><h3>{value(section.heading)}</h3>{section.body.map((paragraph, paragraphIndex) => <p key={paragraphIndex}>{value(paragraph)}</p>)}{section.formula && <FormulaCard title={section.tag === 'game' ? t('formulaGame') : t('formulaTheory')} label={t('engineeringEquation')} formula={value(section.formula)} explanation={section.explanation ? value(section.explanation) : undefined}/>}</div></section>)}
          <div className="takeaway"><span>✦ {t('takeaway')}</span><p>{value(activeLesson.takeaway)}</p></div>
          <div className="lesson-switcher"><button className="quiet-button" disabled={lessons.findIndex((item) => item.id === selected) === 0} onClick={() => setSelected(lessons[Math.max(0, lessons.findIndex((item) => item.id === selected) - 1)].id)}>← {language === 'id' ? 'Sebelumnya' : 'Previous'}</button><button className="primary-button" disabled={lessons.findIndex((item) => item.id === selected) === lessons.length - 1} onClick={() => setSelected(lessons[Math.min(lessons.length - 1, lessons.findIndex((item) => item.id === selected) + 1)].id)}>{language === 'id' ? 'Materi berikutnya' : 'Next lesson'} →</button></div>
        </article>
      </div>
      <section className="quiz-panel"><div className="quiz-heading"><div><div className="eyebrow">{t('knowledgeCheck')}</div><h2>{t('quizTitle')}</h2><p>{t('quizHint')}</p></div><div className="quiz-progress"><strong>{progress}/{quiz.length}</strong><span>{language === 'id' ? 'terjawab' : 'answered'}</span></div></div><div className="quiz-items">{quiz.map((item, index) => <fieldset className="quiz-item" key={index}><legend>{index + 1}. {value(item.question)}</legend><div className="quiz-options">{item.options.map((option, optionIndex) => <label key={optionIndex} className={`quiz-option ${answers[index] === optionIndex ? 'chosen' : ''}`}><input type="radio" name={`quiz-${index}`} checked={answers[index] === optionIndex} onChange={() => { setAnswers((prev) => ({ ...prev, [index]: optionIndex })); setSubmitted(false); }}/><span>{value(option)}</span></label>)}</div>{submitted && <p className={`quiz-explanation ${answers[index] === item.answer ? 'good' : 'needs-review'}`}>{answers[index] === item.answer ? `${t('correct')}. ` : `${t('incorrect')}. `}{value(item.why)}</p>}</fieldset>)}</div><div className="quiz-actions"><button className="primary-button" onClick={submit} disabled={progress !== quiz.length}>{t('checkAnswer')}</button><button className="quiet-button" onClick={() => { setAnswers({}); setSubmitted(false); }}>{language === 'id' ? 'Ulangi kuis' : 'Reset quiz'}</button>{submitted && <strong className="quiz-score">{language === 'id' ? 'Skor' : 'Score'}: {score}/{quiz.length}</strong>}</div></section>
      <section className="references-panel"><div className="eyebrow">{t('modelTransparency')}</div><h2>{t('referenceTitle')}</h2><p>{t('referenceText')}</p><div className="reference-list"><div><b>General reactor physics</b><span>Point kinetics, reactivity, neutron balance</span></div><div><b>Thermal hydraulics</b><span>Control-volume conservation, phase quality, void fraction, CHF/MCPR concepts</span></div><div><b>Software model</b><span>Normalized iodine/xenon proxy, delayed-response index, synthetic dimensionless indices</span></div></div><div className="source-links"><strong>{language === 'id' ? 'Sumber publik untuk pendalaman' : 'Public references for further study'}</strong><a href="https://www.nrc.gov/reactors/power/bwrs" target="_blank" rel="noreferrer">U.S. NRC — Boiling Water Reactors</a><a href="https://www-pub.iaea.org/MTCD/Publications/PDF/TCS-70web.pdf" target="_blank" rel="noreferrer">IAEA — Introduction to Water Cooled Reactor Theory (Xe-135)</a><a href="https://www.nrc.gov/reading-rm/basic-ref/glossary/void-coefficient-of-reactivity" target="_blank" rel="noreferrer">U.S. NRC — Void coefficient of reactivity</a><a href="https://www.nrc.gov/sr0933/section-3-new-generic-issues/issue-63-use-equipment-not-classified-essential-safety-bwr-transient-analysis" target="_blank" rel="noreferrer">U.S. NRC — Critical power ratio and MCPR context</a><a href="https://www.nrc.gov/nureg-ia-0429" target="_blank" rel="noreferrer">U.S. NRC — Feedwater heater transient analysis for ABWR</a><a href="https://www-news.iaea.org/InesScale.aspx" target="_blank" rel="noreferrer">IAEA — INES scope and limitations</a></div></section>
    </section>
  );
}
